const lo = road_width / 2 + 0.15, hi = lo + 3, L = street_length;
const rows = { left: [], right: [] }; let off = 0;
for (let i = 0; i < npoints(0); i++) {
  const P = point(0, 'P', i), az = Math.abs(P[2]);
  if (az < lo || az > hi) { off++; continue; }
  rows[P[2] > 0 ? 'left' : 'right'].push(P[0]);
}
let gap = 0, end = 0, lined = 0;
for (const xs of [rows.left, rows.right]) {
  xs.sort((a, b) => a - b);
  if (xs.length >= 2) lined++;
  if (!xs.length) continue;
  end = Math.max(end, xs[0] + L / 2, L / 2 - xs[xs.length - 1]);
  for (let j = 1; j < xs.length; j++) gap = Math.max(gap, xs[j] - xs[j - 1]);
}
setdetailattrib(0, 'lamp_gap', gap);
setdetailattrib(0, 'lamp_end', end);
setdetailattrib(0, 'lamp_rows', off ? 0 : lined);

const W = house_width, L = street_length, n = Math.max(1, Math.floor((L - 1.6) / (W + 1.6)));
const gap = (L - n * W) / (n + 1), zf = -(road_width / 2 + 3.3);
let roof = Math.floor(rand(seed, 0.5) * 3), col = Math.floor(rand(seed, 0.7) * 5);
for (let i = 0; i < n; i++) {
  const r = (k) => rand(seed, i, k);
  if (i > 0) { roof = (roof + 1 + Math.floor(r(1) * 2)) % 3; col = (col + 1 + Math.floor(r(2) * 4)) % 5; }
  const p = addpoint(0, [-L / 2 + gap + W / 2 + i * (W + gap), 0, zf]);
  setpointattrib(0, 'depth', p, 8 + Math.floor(r(3) * 4));
  setpointattrib(0, 'roof', p, roof);
  setpointattrib(0, 'pitch', p, roof === 2 ? 25 + Math.floor(r(4) * 10) : 32 + Math.floor(r(4) * 14));
  setpointattrib(0, 'colour', p, col);
  setpointattrib(0, 'tiles', p, Math.floor(r(5) * 3));
  setpointattrib(0, 'door_colour', p, Math.floor(r(6) * 4));
  setpointattrib(0, 'shop', p, r(7) < 0.5 ? 1 : 0);
  setpointattrib(0, 'windows', p, Math.max(2, Math.floor(W / (2.1 + r(8)))));
  setpointattrib(0, 'side_windows', p, r(9) < 0.5 ? 1 : 0);
}

const W = house_width, H = floors * 3;
for (let i = 0; i < npoints(0); i++) {
  const P = point(0, 'P', i), D = point(0, 'depth', i), roof = point(0, 'roof', i), t = Math.tan(radians(point(0, 'pitch', i)));
  const r = (k) => rand(seed, i, 20 + k), zc = P[2] - D / 2;
  const n = roof !== 2 && r(0) < 0.4 ? 2 : 1;
  for (let c = 0; c < n; c++) {
    const s = n === 2 ? (c ? 1 : -1) : (r(1) < 0.5 ? -1 : 1);
    let x = P[0], z = zc, ridge;
    if (roof === 0) { ridge = (D + 0.25) / 2 * t; x += s * W * (0.22 + r(2) * 0.08); }
    else if (roof === 1) { ridge = (W + 0.25) / 2 * t; z += s * D * (0.2 + r(2) * 0.06); }
    else { ridge = (Math.min(W, D) + 0.25) / 2 * t; const run = Math.abs(W - D) / 2 * 0.6 * r(2); if (W >= D) x += s * run; else z += s * run; }
    addpoint(0, [x, H + ridge - 1, z]);
  }
  removepoint(0, i);
}

const L = street_length, zb = -33.5, zs = -(road_width / 2 + 3.3) - 2, n = npoints(0);
const line = (x0, z0, x1, z1) => addprim(0, 'polyline', [addpoint(0, [x0, 0, z0]), addpoint(0, [x1, 0, z1])]);
line(-L / 2 + 0.3, zb, L / 2 - 0.3, zb);
line(-L / 2 + 0.3, zs, -L / 2 + 0.3, zb);
line(L / 2 - 0.3, zs, L / 2 - 0.3, zb);
for (let i = 0; i + 1 < n; i++) { const x = (point(0, 'P', i)[0] + point(0, 'P', i + 1)[0]) / 2; line(x, zs, x, zb); }
for (let i = 0; i < n; i++) removepoint(0, i);

const P = point(0, 'P', @ptnum), back = P[2] - @depth - 0.15;
@P = [P[0] + (rand(@ptnum, seed, 31) - 0.5) * house_width * 0.3, 0, (back - 33.5) / 2];
s@kind = rand(@ptnum, seed, 32) < 0.6 ? 'round' : 'conifer';
f@yaw = Math.floor(rand(@ptnum, seed, 33) * 4) * 90;
f@size = 0.85 + rand(@ptnum, seed, 34) * 0.25;

const L = street_length, e = road_width / 2 + 3.15, D = 35 - e;
const zm = e + 0.45 * D, A = Math.min(2.5, 0.1 * D), k = Math.max(1, Math.round(L / 60));
const zAt = (x) => zm + A * Math.sin(2 * Math.PI * k * x / L + 0.6);
const n = Math.ceil((L + 2) / 1.5) + 1, pts = [];
for (let i = 0; i < n; i++) { const x = -L / 2 - 1 + (L + 2) * i / (n - 1); pts.push(addpoint(0, [x, 0, zAt(x)])); }
setprimattrib(0, 'path', addprim(0, 'polyline', pts), 'promenade');
const m = 2 * Math.floor(L / 100) + 1;
for (let j = 0; j < m; j++) {
  const x = -L / 2 + (j + 0.5) * L / m;
  setprimattrib(0, 'path', addprim(0, 'polyline', [addpoint(0, [x, 0, e - 1]), addpoint(0, [x, 0, zAt(x)])]), 'entrance');
}
setdetailattrib(0, 'plaza_z', zAt(0));

const T = @tangent, s = @side;
f@yaw = degrees(Math.atan2(s * T[2], -s * T[0]));
@P.y = 0.1;

const R = Math.min(5, 0.18 * (35 - road_width / 2 - 3.15)) + 0.9, zc = detail(1, 'plaza_z');
for (const a of [45, 135, 225, 315]) {
  const t = radians(a), p = addpoint(0, [R * Math.cos(t), 0.1, zc + R * Math.sin(t)]);
  setpointattrib(0, 'yaw', p, degrees(Math.atan2(-Math.cos(t), -Math.sin(t))));
}

@P.y = 0.1;
f@yaw = Math.floor(rand(@ptnum, seed, 3) * 4) * 90;
f@size = 0.85 + rand(@ptnum, seed, 4) * 0.3;

@P.y = 0.1;
f@yaw = rand(@ptnum, seed, 5) * 360;
f@size = 0.8 + rand(@ptnum, seed, 6) * 0.45;

const L = street_length, z = road_width / 2 + 3.15 + 0.9, m = 2 * Math.floor(L / 100) + 1;
let x0 = -L / 2 + 1.6;
const run = (a, b) => { if (b - a > 1) addprim(0, 'polyline', [addpoint(0, [a, 0.1, z]), addpoint(0, [b, 0.1, z])]); };
for (let j = 0; j < m; j++) { const x = -L / 2 + (j + 0.5) * L / m; run(x0, x - 2.1); x0 = x + 2.1; }
run(x0, L / 2 - 1.6);
